function renderProjects(){const el=$('#projectList');const q=($('#projectSearch')?.value||'').trim().toLowerCase();const filtered=projects.filter(p=>!q||[p.title,p.client,p.category,p.service,p.type,p.status,p.visibility].some(v=>String(v||'').toLowerCase().includes(q)));const count=$('#projectResultCount');if(count)count.textContent=`${filtered.length} / ${projects.length}`;el.innerHTML=filtered.map(p=>`<div class="project-item"><img src="${esc(p.coverImage||'assets/amazon-01.svg')}" alt=""><div><strong>${esc(p.title)}</strong><small>${esc(p.category)} · ${esc(p.status)} · ${esc(p.visibility)}${p.featured?' · FEATURED':''}${p.sliderEnabled!==false?' · SLIDER ON':' · SLIDER OFF'}${p.sliderTransition&&p.sliderTransition!=='AUTO'?' · '+esc(p.sliderTransition):''}${p.clientOnly?' · CLIENT ONLY':''}</small></div><div class="item-actions"><button type="button" class="admin-btn js-edit" data-id="${esc(p.id)}">EDIT</button><button type="button" class="admin-btn js-share" data-id="${esc(p.id)}">SHARE</button>${p.accessTokenHash?'<button type="button" class="admin-btn js-revoke" data-id="'+esc(p.id)+'">REVOKE</button>':''}<button type="button" class="admin-btn danger js-delete" data-id="${esc(p.id)}">DELETE</button></div></div>`).join('')||'<p class="notice">No projects match your search.</p>';el.querySelectorAll('.js-edit').forEach(b=>b.addEventListener('click',()=>editProject(b.dataset.id)));el.querySelectorAll('.js-share').forEach(b=>b.addEventListener('click',()=>shareProject(b.dataset.id)));el.querySelectorAll('.js-revoke').forEach(b=>b.addEventListener('click',()=>revokeShare(b.dataset.id)));el.querySelectorAll('.js-delete').forEach(b=>b.addEventListener('click',()=>deleteProject(b.dataset.id)))}
