function setEditorPreview(){const body=$('#contentBody').value||'';const preview=$('#contentPreview');if(!preview)return;let h=esc(body);h=h.replace(/!\[([^\]]*)\]\(((?:https?:\/\/|\/)[^)]+)\)/g,'<figure class="editor-inline-image"><img src="$2" alt="$1"><figcaption>$1</figcaption></figure>');h=h.replace(/^### (.*)$/gm,'<h4>$1</h4>').replace(/^## (.*)$/gm,'<h3>$1</h3>').replace(/^# (.*)$/gm,'<h2>$1</h2>').replace(/^> (.*)$/gm,'<blockquote>$1</blockquote>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>').replace(/\[(.*?)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>');h=h.replace(/(?:^|\n)((?:[-*] .+(?:\n|$))+)/g,(m)=>'<ul>'+m.trim().split(/\n/).map(x=>'<li>'+x.replace(/^[-*] /,'')+'</li>').join('')+'</ul>');h=h.replace(/(?:^|\n)((?:\d+\. .+(?:\n|$))+)/g,(m)=>'<ol>'+m.trim().split(/\n/).map(x=>'<li>'+x.replace(/^\d+\. /,'')+'</li>').join('')+'</ol>');h=h.replace(/\n\n+/g,'</p><p>').replace(/\n/g,'<br>');preview.innerHTML='<p>'+h+'</p>'}
function insertMarkdown(prefix,suffix=''){const ta=$('#contentBody');if(!ta)return;const a=ta.selectionStart,b=ta.selectionEnd,v=ta.value;const selected=v.slice(a,b)||'text';ta.value=v.slice(0,a)+prefix+selected+suffix+v.slice(b);ta.focus();ta.setSelectionRange(a+prefix.length,a+prefix.length+selected.length);setEditorPreview()}
function insertList(ordered=false){const ta=$('#contentBody');if(!ta)return;const a=ta.selectionStart,b=ta.selectionEnd,v=ta.value;const selected=v.slice(a,b)||'List item';const lines=selected.split('\n').map((line,i)=>`${ordered?i+1+'.':'-'} ${line.replace(/^[-*] |^\d+\. /,'')}`);const text=lines.join('\n');ta.value=v.slice(0,a)+text+v.slice(b);ta.focus();ta.setSelectionRange(a,a+text.length);setEditorPreview()}
$$('[data-md]').forEach(b=>b.addEventListener('click',()=>{const x=b.dataset.md;if(x==='h2')insertMarkdown('## ','');if(x==='bold')insertMarkdown('**','**');if(x==='italic')insertMarkdown('*','*');if(x==='link')insertMarkdown('[','](https://)');if(x==='ul')insertList(false);if(x==='ol')insertList(true);if(x==='quote')insertMarkdown('> ','')}));$('#contentBody')?.addEventListener('input',setEditorPreview);

async function fillContent(cOrId, slug){let c=typeof cOrId==='object'&&cOrId?cOrId:null;let recordId=String(c?.id||cOrId||'').trim();if(recordId==='undefined'||recordId==='null')recordId='';let recordSlug=String(c?.slug||slug||'').trim();if((!recordId||recordId==='')&&recordSlug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(recordSlug));c=d?.content||null;recordId=String(c?.id||'').trim()}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!recordId&&recordSlug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(recordSlug));c=d?.content||null;recordId=String(c?.id||'').trim()}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!recordId){msg($('#contentMsg'),'This content record could not be resolved. The CMS has no usable ID or slug for this item.',false);return;}if(!c){try{const d=await api('/admin/content/'+encodeURIComponent(recordId));c=d?.content||null}catch(e){msg($('#contentMsg'),e.message,false);return}}if(!c){msg($('#contentMsg'),'Content record could not be loaded.',false);return;}$('#cid').value=recordId;$('#contentTitle').value=c.title;$('#contentSlug').value=c.slug;$('#contentType').value=c.type||'BLOG';$('#contentCategory').value=c.category||'';$('#contentExcerpt').value=c.excerpt||'';$('#contentBody').value=c.body||'';$('#contentCover').value=c.coverImage||'';$('#contentTags').value=(c.tags||[]).join(', ');$('#contentAuthor').value=c.author||'';$('#contentSeoTitle').value=c.seoTitle||'';$('#contentSeoDescription').value=c.seoDescription||'';window.fillContentSeo?.(c);$('#contentStatus').value=c.status;$('#contentScheduledAt').value=isoToLocal(c.scheduledAt);$('#contentFeatured').checked=!!c.featured;$('#contentOrder').value=c.sortOrder||0;setEditorPreview();$('#contentHeading').textContent='Edit content';document.querySelector('[data-tab="content"]').click();$('#contentForm').scrollIntoView({behavior:'smooth',block:'start'})}
window.editContent=fillContent;
window.deleteContent=async(id,slug)=>{if(!confirm('Delete this content?'))return;let recordId=String(id||'').trim();if((!recordId||recordId==='undefined'||recordId==='null')&&slug){try{const d=await api('/admin/content/by-slug/'+encodeURIComponent(slug));recordId=String(d?.content?.id||'').trim()}catch(e){alert(e.message);return}}if(!recordId){alert('This content cannot be deleted because its database record could not be resolved.');return}try{await api('/admin/content/'+encodeURIComponent(recordId),{method:'DELETE'});await load()}catch(e){alert(e.message)}};
$('#contentCoverUpload')?.addEventListener('change',async()=>{const f=$('#contentCoverUpload').files[0];if(!f)return;try{msg($('#contentUploadMsg'),'Uploading cover image...',true);const d=await uploadImage(f);$('#contentCover').value=d.publicUrl;msg($('#contentUploadMsg'),'Cover uploaded. Save content.',true)}catch(e){msg($('#contentUploadMsg'),e.message)}});
$('#insertContentImage')?.addEventListener('click',()=>$('#contentInlineImageUpload')?.click());$('#contentInlineImageUpload')?.addEventListener('change',async()=>{const f=$('#contentInlineImageUpload').files[0];if(!f)return;try{msg($('#contentImageMsg'),'Uploading inline image...',true);const ta=$('#contentBody');const cursor=ta.selectionStart||ta.value.length;const d=await uploadImage(f);const alt=(f.name||'Content image').replace(/\.[^.]+$/,'').replace(/[-_]+/g,' ');const md=`![${alt}](${d.publicUrl})`;ta.value=ta.value.slice(0,cursor)+md+ta.value.slice(cursor);ta.focus();ta.setSelectionRange(cursor+md.length,cursor+md.length);setEditorPreview();msg($('#contentImageMsg'),`Image inserted via ${d.provider}. Save the content to keep it.`,true)}catch(e){msg($('#contentImageMsg'),e.message)}finally{$('#contentInlineImageUpload').value=''}});
$('#contentTitle')?.addEventListener('input',()=>{const slugEl=$('#contentSlug');if(!$('#cid').value.trim()&&slugEl&&!slugEl.dataset.edited){slugEl.value=$('#contentTitle').value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120)}});
