const DEFAULT_SLIDER_SETTINGS={enabled:true,mode:'AUTO_MANUAL',interval:5,pauseHover:true,pauseFocus:true,pauseHidden:true,loop:true,arrows:true,counter:true,progress:true,dots:false,keyboard:true,wheel:false,swipe:true,transitionMode:'RANDOM',fixedTransition:'MASK',duration:900,easing:'SMOOTH',preload:true,randomStart:false,drag:true,clickOpen:true,maxSlides:8,mobileAuto:true,mobileInterval:4,mobileArrows:false,mobileSwipe:true,reducedMotion:true,pauseOffscreen:true,lazy:true,showThumbnails:true,showDetails:true,eyebrow:'FEATURED WORK',headline:'Design that makes products hard to ignore.',description:'Selected brand, commerce and digital work.',reflectionEnabled:true,reflectionDirection:'LEFT_TO_RIGHT',reflectionIntensity:'SUBTLE',reflectionWidth:22,reflectionAngle:-14,reflectionDuration:1100,reflectionDelay:320,mobileReflection:false};
const DEFAULT_PARTICLE_CONFIG={enabled:true,style:'NEURAL',density:46,speed:.22,linkDistance:150,nodeSize:1,lineOpacity:.16,depth:1,mouseStrength:.35,pulse:.35};
const particleFields={enabled:'particleEnabled',style:'particleStyle',density:'particleDensity',speed:'particleSpeed',linkDistance:'particleLinkDistance',nodeSize:'particleNodeSize',lineOpacity:'particleLineOpacity',depth:'particleDepth',mouseStrength:'particleMouseStrength',pulse:'particlePulse'};
function fillParticleSettings(cfg={}){const x={...DEFAULT_PARTICLE_CONFIG,...(cfg||{})};currentParticleConfig=x;Object.entries(particleFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;if(el.type==='checkbox')el.checked=!!x[k];else el.value=x[k]??''});updateParticleValueLabels()}
function readParticleSettings(){const x={};Object.entries(particleFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;x[k]=el.type==='checkbox'?el.checked:(el.type==='range'?Number(el.value):el.value)});return x}
function updateParticleValueLabels(){const map={particleSpeed:'particleSpeedValue',particleDensity:'particleDensityValue',particleLinkDistance:'particleLinkDistanceValue',particleNodeSize:'particleNodeSizeValue',particleDepth:'particleDepthValue',particleMouseStrength:'particleMouseStrengthValue',particlePulse:'particlePulseValue',particleLineOpacity:'particleLineOpacityValue'};Object.entries(map).forEach(([a,b])=>{const el=$('#'+a),out=$('#'+b);if(el&&out){const v=Number(el.value);out.textContent=(a==='particleDensity'||a==='particleLinkDistance')?String(Math.round(v)):v.toFixed(2)}})}
let currentParticleConfig={},currentSliderConfig={};
const sliderFields={enabled:'sliderEnabledGlobal',mode:'sliderMode',interval:'sliderInterval',pauseHover:'sliderPauseHover',pauseFocus:'sliderPauseFocus',pauseHidden:'sliderPauseHidden',loop:'sliderLoop',arrows:'sliderArrows',counter:'sliderCounter',progress:'sliderProgress',dots:'sliderDots',keyboard:'sliderKeyboard',wheel:'sliderWheel',swipe:'sliderSwipe',transitionMode:'sliderTransitionMode',fixedTransition:'sliderFixedTransition',duration:'sliderDuration',easing:'sliderEasing',preload:'sliderPreload',randomStart:'sliderRandomStart',drag:'sliderDrag',clickOpen:'sliderClickOpen',maxSlides:'sliderMaxSlides',mobileAuto:'sliderMobileAuto',mobileInterval:'sliderMobileInterval',mobileArrows:'sliderMobileArrows',mobileSwipe:'sliderMobileSwipe',reducedMotion:'sliderReducedMotion',pauseOffscreen:'sliderPauseOffscreen',lazy:'sliderLazy',showThumbnails:'sliderShowThumbnails',showDetails:'sliderShowDetails',eyebrow:'sliderEyebrow',headline:'sliderHeadlineGlobal',description:'sliderDescriptionGlobal',reflectionEnabled:'sliderReflectionEnabled',reflectionDirection:'sliderReflectionDirection',reflectionIntensity:'sliderReflectionIntensityGlobal',reflectionWidth:'sliderReflectionWidth',reflectionAngle:'sliderReflectionAngle',reflectionDuration:'sliderReflectionDuration',reflectionDelay:'sliderReflectionDelay',mobileReflection:'sliderMobileReflection'};
