function readSliderSettings(){const x={...currentSliderConfig};Object.entries(sliderFields).forEach(([k,id])=>{const el=$('#'+id);if(!el)return;x[k]=el.type==='checkbox'?el.checked:(el.type==='number'?Number(el.value):el.value)});x.particleConfig={...currentParticleConfig};return x}
