function normalizeSocialColor(value){const color=String(value||'').trim().replace(/^#/,'');return /^[0-9a-f]{6}$/i.test(color)?`#${color.toLowerCase()}`:'#c6ff4c'}
function socialIconUrl(item){const custom=String(item.iconUrl||'').trim();if(custom)return custom;const slug=String(item.icon||'linktree').trim().toLowerCase().replace(/[^a-z0-9.-]/g,'')||'linktree',color=normalizeSocialColor(item.color);return `https://api.iconify.design/simple-icons/${slug}.svg?color=${encodeURIComponent(color)}`}
function socialFallbackUrl(item){const slug=String(item.icon||'').toLowerCase(),special={linkedin:'in',instagram:'IG',github:'GH',behance:'Bē',dribbble:'Dr',facebook:'f',x:'X',youtube:'YT',pinterest:'P',tiktok:'TT',whatsapp:'WA',medium:'M',discord:'DC',gmail:'@'},letters=special[slug]||String(item.label||'Link').replace(/[^a-z0-9]/gi,'').slice(0,2).toUpperCase()||'↗',color=normalizeSocialColor(item.color),svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><text x="24" y="31" text-anchor="middle" font-family="Arial,sans-serif" font-size="22" font-weight="700" fill="${color}">${letters}</text></svg>`;return `data:image/svg+xml,${encodeURIComponent(svg)}`}
