function socialRow(item={},index=0){const color=normalizeSocialColor(item.color),size=Math.min(40,Math.max(14,Number(item.size)||18)),options=SOCIAL_PRESETS.map(([label,slug])=>`<option value="${esc(slug)}" ${slug===(item.icon||'')?'selected':''}>${esc(label)}</option>`).join('');return `<article class="social-manager-row" data-social-index="${index}"><div class="social-row-head"><div class="social-manager-preview" style="--social-preview-size:${size}px"><img src="${esc(socialIconUrl({...item,color,size}))}" data-social-fallback="${esc(socialFallbackUrl({...item,color,size}))}" alt=""><strong>${esc(item.label||'Social profile')}</strong></div><div class="social-row-actions"><button type="button" class="admin-btn" data-social-move="up" aria-label="Move up">↑</button><button type="button" class="admin-btn" data-social-move="down" aria-label="Move down">↓</button><button type="button" class="admin-btn danger" data-social-remove>REMOVE</button></div></div><div class="social-manager-fields"><label>LABEL<input data-social-field="label" value="${esc(item.label||'')}"></label><label>PROFILE URL<input data-social-field="url" type="url" placeholder="https://..." value="${esc(item.url||'')}"></label><label>ICON PRESET<select data-social-preset>${options}</select></label><label>ICON SLUG<input data-social-field="icon" value="${esc(item.icon||'linktree')}" placeholder="simpleicons slug"></label><label>CUSTOM ICON URL (OPTIONAL)<input data-social-field="iconUrl" value="${esc(item.iconUrl||'')}" placeholder="https://.../icon.svg"></label><label>ICON COLOR<div class="social-color-control"><input data-social-color type="color" value="${color}"><input data-social-field="color" value="${color}" maxlength="7"></div></label><label>ICON SIZE <output>${size}px</output><input data-social-field="size" type="range" min="14" max="40" step="1" value="${size}"></label><label class="toggle-field compact"><input data-social-field="visible" type="checkbox" ${item.visible!==false?'checked':''}><span><strong>SHOW ON SITE</strong><small>Hide without deleting this profile.</small></span></label></div></article>`}
function readSocialManager(){return $$('#socialLinksManager .social-manager-row').map((row,sortOrder)=>{const get=name=>row.querySelector(`[data-social-field="${name}"]`);return{id:row.dataset.socialId||`social-${Date.now()}-${sortOrder}`,label:get('label')?.value.trim()||'Profile',url:get('url')?.value.trim()||'',icon:get('icon')?.value.trim()||'linktree',iconUrl:get('iconUrl')?.value.trim()||'',color:normalizeSocialColor(get('color')?.value),size:Math.min(40,Math.max(14,Number(get('size')?.value)||18)),visible:!!get('visible')?.checked,sortOrder}}).filter(item=>item.url)}
function renderSocialManager(){const root=$('#socialLinksManager');if(!root)return;experienceSettings.socialLinks.sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0));root.innerHTML=experienceSettings.socialLinks.length?experienceSettings.socialLinks.map(socialRow).join(''):'<div class="social-manager-empty">No social profiles yet. Click ADD SOCIAL PROFILE.</div>';root.querySelectorAll('.social-manager-row').forEach((row,index)=>{row.dataset.socialId=experienceSettings.socialLinks[index]?.id||`social-${Date.now()}-${index}`;row.addEventListener('input',event=>{const field=event.target.dataset.socialField;if(field){const value=event.target.type==='checkbox'?event.target.checked:event.target.value;experienceSettings.socialLinks[index][field]=field==='size'?Number(value):value;renderPublicProfilePreview()}if(event.target.matches('[data-social-color]')){const text=row.querySelector('[data-social-field="color"]');text.value=event.target.value;experienceSettings.socialLinks[index].color=event.target.value;renderPublicProfilePreview()}if(event.target.matches('[data-social-field="size"]'))event.target.closest('label').querySelector('output').textContent=`${event.target.value}px`});row.addEventListener('change',event=>{if(event.target.matches('[data-social-preset]')){row.querySelector('input[data-social-field="icon"]').value=event.target.value;experienceSettings.socialLinks[index].icon=event.target.value;renderPublicProfilePreview()}});row.querySelector('[data-social-remove]')?.addEventListener('click',()=>{experienceSettings.socialLinks.splice(index,1);renderSocialManager();renderPublicProfilePreview()});row.querySelectorAll('[data-social-move]').forEach(button=>button.addEventListener('click',()=>{const next=button.dataset.socialMove==='up'?index-1:index+1;if(next<0||next>=experienceSettings.socialLinks.length)return;[experienceSettings.socialLinks[index],experienceSettings.socialLinks[next]]=[experienceSettings.socialLinks[next],experienceSettings.socialLinks[index]];experienceSettings.socialLinks.forEach((item,sortOrder)=>item.sortOrder=sortOrder);renderSocialManager();renderPublicProfilePreview()}))})}
function renderPublicProfilePreview(){const root=$('#experienceSocialPreview');if(!root)return;const rows=$('#socialLinksManager')?readSocialManager():experienceSettings.socialLinks;root.innerHTML=rows.filter(item=>item.visible!==false&&item.url).length?rows.filter(item=>item.visible!==false&&item.url).map(item=>`<a href="${esc(/^https?:\/\//i.test(item.url)?item.url:'#')}" target="_blank" rel="noreferrer" title="Preview ${esc(item.label||'Profile')}" style="--social-preview-size:${Math.min(40,Math.max(14,Number(item.size)||18))}px"><img src="${esc(socialIconUrl(item))}" data-social-fallback="${esc(socialFallbackUrl(item))}" alt=""><span>${esc(item.label||'Profile')}</span></a>`).join(''):'<span class="muted">ADD AND ENABLE A SOCIAL PROFILE TO PREVIEW IT</span>'}
function upgradePublicProfileControls(){const section=$('#experienceControls'),socialCard=$('#settingLinkedin')?.closest('.settings-card'),cv=$('.experience-cv');if(!section||!socialCard||!cv)return;section.querySelector('.settings-card-head h3').textContent='Public profile, navigation & private demo.';section.querySelector('.settings-card-head .notice').textContent='Manage the public CV, social profiles and navigation behavior from one clear workspace.';socialCard.classList.add('public-contact-card');socialCard.removeAttribute('aria-hidden');['#settingLinkedin','#settingInstagram','#settingGithub','#settingBehance','#settingDribbble'].forEach(selector=>$(selector)?.closest('label')?.classList.add('hidden'));const socialHeading=socialCard.querySelector('.settings-card-head');if(socialHeading){socialHeading.querySelector('.kicker').textContent='PUBLIC CONTACT';socialHeading.querySelector('h3').textContent='Public email address.';socialHeading.querySelector('.notice').textContent='Social profiles are managed in the visual icon manager above.'}if(socialCard.parentElement!==section)section.insertBefore(socialCard,section.querySelector('.admin-actions'));if(!$('#settingCvTest')){$('#settingCvCurrent').insertAdjacentHTML('afterend','<a class="admin-btn cv-test-button hidden" id="settingCvTest" href="/api/public/cv" target="_blank" rel="noopener">TEST CV DOWNLOAD ↗</a>')}const status=section.querySelector('.experience-social-status');if(status&&!$('#socialLinksManager'))status.innerHTML='<div class="social-manager-heading"><div><span class="kicker">SOCIAL ICON MANAGER</span><h3>Editable public profiles.</h3><p class="notice">Choose a preset or enter any Simple Icons slug. Set color, size, order and visibility here. A custom icon URL overrides the preset icon.</p></div><button type="button" class="admin-btn primary" id="addSocialLink">+ ADD SOCIAL PROFILE</button></div><div id="experienceSocialPreview" class="experience-social-preview"></div><div id="socialLinksManager" class="social-links-manager"></div>';$('#addSocialLink')?.addEventListener('click',()=>{experienceSettings.socialLinks.push({id:`social-${Date.now()}`,label:'New profile',url:'',icon:'linktree',iconUrl:'',color:'#c6ff4c',size:18,visible:true,sortOrder:experienceSettings.socialLinks.length});renderSocialManager();renderPublicProfilePreview()});renderSocialManager();renderPublicProfilePreview()}
function ensureExperienceControls(){const panel=$('.site-settings-panel'),form=$('#settingsForm');if(!panel||!form||$('#experienceControls'))return;const section=document.createElement('section');section.id='experienceControls';section.className='settings-card experience-controls';section.innerHTML=`<div class="settings-card-head"><div><span class="kicker">SITE EXPERIENCE</span><h3>Navigation, demo preview & CV.</h3><p class="notice">These controls extend the current site without changing published content or replacing existing settings.</p></div><span class="settings-badge">ADDITIVE</span></div><div class="experience-grid"><label class="toggle-field"><input id="settingStickyNavigation" type="checkbox"><span><strong>ALWAYS-VISIBLE NAVIGATION</strong><small>Keep the public navbar visible while scrolling instead of auto-hiding it.</small></span></label><label class="toggle-field"><input id="settingDemoPreview" type="checkbox"><span><strong>ADMIN DEMO PREVIEW</strong><small>Local admin-only preview. It never publishes demo records to the database.</small></span></label><div class="experience-demo-actions"><a class="admin-btn" id="openDemoPreview" href="/?demo=1" target="_blank" rel="noopener">OPEN FULL DEMO PREVIEW ↗</a><small>Preview includes sample projects, brands, journal, testimonials and skills when those areas need examples.</small></div><div class="experience-cv"><span class="kicker">PUBLIC CV</span><label>BUTTON LABEL<input id="settingCvLabel" value="DOWNLOAD CV"></label><label>UPLOAD / REPLACE PDF<input id="settingCvFile" type="file" accept="application/pdf,.pdf"></label><div id="settingCvCurrent" class="notice">No CV uploaded.</div><label class="ops-check"><input id="settingCvRemove" type="checkbox"> REMOVE CV BUTTON FROM PUBLIC SITE</label></div><div class="experience-social-status"><span class="kicker">SOCIAL LINKS</span><p class="notice">LinkedIn, Instagram, GitHub, Behance and Dribbble are managed in Contact & social below. Saved URLs will now render as visible public icon links.</p><div id="experienceSocialPreview" class="experience-social-preview"></div></div><div class="experience-email-status"><span class="kicker">CONTACT EMAIL</span><p class="notice">Inquiry recipient and subject are managed below. Without an owned verified domain, CMS replies use your device’s email app; stored inquiries and Resend notification delivery remain unchanged.</p></div></div><div class="admin-actions"><button type="button" class="admin-btn primary" id="saveExperienceControls">SAVE EXPERIENCE SETTINGS</button></div><div id="experienceMsg" class="notice"></div>`;form.parentNode.insertBefore(section,form);$('#settingDemoPreview').addEventListener('change',updateDemoPreviewControl);$('#saveExperienceControls').addEventListener('click',saveExperienceControls)}
function updateDemoPreviewControl(){const enabled=$('#settingDemoPreview')?.checked;try{localStorage.setItem('adminDemoPreview',enabled?'true':'false')}catch{}const link=$('#openDemoPreview');if(link){link.href=enabled?'/?demo=1':'/';link.textContent=enabled?'OPEN FULL DEMO PREVIEW ↗':'OPEN LIVE SITE ↗'}}
function fillExperienceControls(x){ensureExperienceControls();experienceSettings={footerConfig:x.footerConfig&&typeof x.footerConfig==='object'&&!Array.isArray(x.footerConfig)?{...x.footerConfig}:{},aboutConfig:x.aboutConfig&&typeof x.aboutConfig==='object'&&!Array.isArray(x.aboutConfig)?{...x.aboutConfig}:{},socialLinks:Array.isArray(x.socialLinks)&&x.socialLinks.length?x.socialLinks.map((item,index)=>({...item,id:item.id||`social-${index}`,color:normalizeSocialColor(item.color),size:Math.min(40,Math.max(14,Number(item.size)||18)),visible:item.visible!==false,sortOrder:Number.isFinite(Number(item.sortOrder))?Number(item.sortOrder):index})):legacySocialLinks(x)};upgradePublicProfileControls();renderSocialManager();$('#settingStickyNavigation').checked=experienceSettings.footerConfig.stickyNavigation!==false;try{$('#settingDemoPreview').checked=localStorage.getItem('adminDemoPreview')!=='false'}catch{$('#settingDemoPreview').checked=true}updateDemoPreviewControl();$('#settingCvLabel').value=experienceSettings.aboutConfig.cvLabel||'DOWNLOAD CV';$('#settingCvRemove').checked=false;const current=$('#settingCvCurrent');if(current)current.innerHTML=experienceSettings.aboutConfig.cvUrl?`Current: <a href="/api/public/cv" target="_blank" rel="noopener">${esc(experienceSettings.aboutConfig.cvFilename||'CV.pdf')} ↗</a>`:'No CV uploaded.';const test=$('#settingCvTest');if(test){test.classList.toggle('hidden',!experienceSettings.aboutConfig.cvUrl);test.href='/api/public/cv'}renderPublicProfilePreview();setTimeout(renderPublicProfilePreview,0)}
async function uploadCvDocument(file){if(!file)return null;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))throw new Error('Choose a PDF file for the CV.');if(file.size>4_000_000)throw new Error('CV PDF must be 4 MB or smaller.');const response=await fetch('/api/admin/documents/upload',{method:'POST',credentials:'include',headers:{'Content-Type':'application/pdf','X-Filename':encodeURIComponent(file.name)},body:file});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'CV upload failed.');return data}
async function saveExperienceControls(){const button=$('#saveExperienceControls'),message=$('#experienceMsg');try{button.disabled=true;message.textContent='Saving experience settings…';let about={...experienceSettings.aboutConfig},footer={...experienceSettings.footerConfig,stickyNavigation:$('#settingStickyNavigation').checked};const socialLinks=readSocialManager();for(const item of socialLinks){if(!/^https?:\/\//i.test(item.url))throw new Error(`${item.label}: profile URL must start with http:// or https://.`);if(item.iconUrl&&!/^(https?:\/\/|\/)/i.test(item.iconUrl))throw new Error(`${item.label}: custom icon URL must be an https URL or a site-relative path.`)}const file=$('#settingCvFile').files?.[0];if(file){const uploaded=await uploadCvDocument(file);about={...about,cvUrl:uploaded.publicUrl,cvFilename:file.name,cvLabel:$('#settingCvLabel').value.trim()||'DOWNLOAD CV'}}else if($('#settingCvRemove').checked){about={...about,cvUrl:null,cvFilename:null,cvLabel:$('#settingCvLabel').value.trim()||'DOWNLOAD CV'}}else about={...about,cvLabel:$('#settingCvLabel').value.trim()||'DOWNLOAD CV'};await Promise.all([api('/admin/maintenance/site-config',{method:'PATCH',body:JSON.stringify({footerConfig:footer,aboutConfig:about,socialLinks})}),api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify({email:$('#settingEmail').value||null,linkedin:null,instagram:null,github:null,behance:null,dribbble:null})})]);experienceSettings={footerConfig:footer,aboutConfig:about,socialLinks};updateDemoPreviewControl();message.className='success';message.textContent='Public profile, social icons, navigation and CV settings saved.';showToast('Public profile settings saved.');await loadMaintenance()}catch(e){message.className='error';message.textContent=e.message}finally{button.disabled=false}}
async function loadMaintenance(){try{const [st,settings,t,a,iq,rv]=await Promise.all([api('/admin/maintenance/status'),api('/admin/maintenance/settings'),api('/admin/maintenance/testimonials'),api('/admin/maintenance/activity'),api('/admin/maintenance/inquiries'),api('/admin/maintenance/reviews')]);const vals=[st.database?'OK':'ERROR',st.storage==='configured'?'CONFIGURED':'LOCAL',st.counts.projects,st.counts.content,st.counts.media];$('#systemStatus').innerHTML=vals.map((v,i)=>`<div><strong>${esc(v)}</strong><span>${['DATABASE','STORAGE','PROJECTS','CONTENT','MEDIA'][i]}</span></div>`).join('');const x=settings.settings||{};fillExperienceControls(x);fillSliderSettings(x.sliderConfig||{});fillParticleSettings(x.sliderConfig?.particleConfig||{});renderSkills(Array.isArray(x.skillsConfig)?x.skillsConfig:[]);['SiteName','Title','Email','InquiryRecipientEmail','InquirySubject','Phone','Location','AvailabilityLabel','Linkedin','Behance','Dribbble','Instagram','Github','MetaTitle','MetaDescription','OgImage','HeroImage','HeroLeadText'].forEach(k=>{const id='#setting'+k;if($(id))$(id).value=x[k.charAt(0).toLowerCase()+k.slice(1)]||''});$('#settingAvailability').checked=!!x.availability;$('#settingHeroLeadText').value=x.heroLeadText||'I DESIGN';$('#settingHeroTypewriterPhrases').value=Array.isArray(x.heroTypewriterPhrases)?x.heroTypewriterPhrases.join('\n'):'BRANDS THAT SELL.';updateHeroCopyPreview();updateSiteSeoPreview();const heroPreview=$('#heroImagePreview');if(heroPreview&&x.heroImage)heroPreview.innerHTML=`<img src="${esc(x.heroImage)}" alt="Hero preview">`;renderTestimonials(t.testimonials||[]);$('#inquiryList').innerHTML=(iq.inquiries||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.name)} · ${esc(x.service||'General')}</strong><small>${esc(x.email)} · ${esc(x.status)} · ${new Date(x.createdAt).toLocaleString()}<br>${esc(x.company||'')}${x.projectType?' · '+esc(x.projectType):''}<br>${esc(x.message)}</small><label>INTERNAL NOTES<textarea class="inquiry-notes" data-id="${esc(x.id)}">${esc(x.internalNotes||'')}</textarea></label><div class="admin-actions"><a class="admin-btn" href="mailto:${encodeURIComponent(x.email)}?subject=${encodeURIComponent('Re: '+(x.projectType||x.service||'Your project inquiry'))}">REPLY VIA EMAIL</a></div></div><select class="inquiry-status" data-id="${esc(x.id)}"><option ${x.status==='NEW'?'selected':''}>NEW</option><option ${x.status==='READ'?'selected':''}>READ</option><option ${x.status==='REPLIED'?'selected':''}>REPLIED</option><option ${x.status==='QUALIFIED'?'selected':''}>QUALIFIED</option><option ${x.status==='WON'?'selected':''}>WON</option><option ${x.status==='CLOSED'?'selected':''}>CLOSED</option></select></div>`).join('')||'<p class="notice">No inquiries yet.</p>';$$('.inquiry-status').forEach(sel=>sel.addEventListener('change',async()=>{await api('/admin/maintenance/inquiries/'+sel.dataset.id,{method:'PATCH',body:JSON.stringify({status:sel.value})});loadMaintenance()}));$$('.inquiry-notes').forEach(field=>field.addEventListener('change',async()=>{await api('/admin/maintenance/inquiries/'+field.dataset.id,{method:'PATCH',body:JSON.stringify({internalNotes:field.value||null})});showToast('Inquiry notes saved.')}));$('#activityList').innerHTML=(a.activity||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.action)}</strong><small>${esc(x.entity)} · ${esc(x.label||'')} · ${new Date(x.createdAt).toLocaleString()}</small></div></div>`).join('')||'<p class="notice">No activity yet.</p>';$('#reviewList').innerHTML=(rv.reviews||[]).map(x=>`<div class="project-item"><div><strong>${esc(x.decision)}</strong><small>${esc(x.clientName)}${x.clientEmail?' · '+esc(x.clientEmail):''} · ${new Date(x.createdAt).toLocaleString()}<br>${esc(x.comment||'No comment')}</small></div></div>`).join('')||'<p class="notice">No client reviews yet.</p>'}catch(e){$('#maintenanceMsg').textContent=e.message}}

