const HERO_TYPEWRITER_PRESETS=Object.freeze({EDITORIAL:{label:'EDITORIAL',help:'Balanced speed with a lime line cursor.',typeSpeed:42,typeRandom:35,pause:2400,eraseSpeed:25,nextDelay:650,startDelay:220,loop:true},QUICK_CUT:{label:'QUICK CUT',help:'Fast, energetic rhythm with a dot cursor.',typeSpeed:22,typeRandom:12,pause:1650,eraseSpeed:14,nextDelay:280,startDelay:120,loop:true},CINEMATIC:{label:'CINEMATIC',help:'Slow, deliberate reveals with an elegant cursor.',typeSpeed:68,typeRandom:38,pause:3600,eraseSpeed:34,nextDelay:900,startDelay:420,loop:true},TERMINAL:{label:'TERMINAL',help:'Precise digital cadence with a block cursor.',typeSpeed:30,typeRandom:5,pause:2050,eraseSpeed:18,nextDelay:420,startDelay:160,loop:true},QUIET:{label:'QUIET',help:'Spacious and subtle pacing with an underline cursor.',typeSpeed:50,typeRandom:18,pause:4200,eraseSpeed:30,nextDelay:1100,startDelay:300,loop:true}});
function heroTypewriterPresetFor(config={}){return Object.entries(HERO_TYPEWRITER_PRESETS).find(([,preset])=>['typeSpeed','typeRandom','pause','eraseSpeed','nextDelay','startDelay','loop'].every(key=>config[key]===preset[key]))?.[0]||'EDITORIAL'}
function ensureHeroTypewriterPreset(){let field=$('#settingTypewriterPreset');if(field)return field;const phrases=$('#settingHeroTypewriterPhrases');if(!phrases)return null;const label=document.createElement('label');label.className='typewriter-preset-field';label.innerHTML='TYPEWRITER MOTION PRESET<select id="settingTypewriterPreset"><option value="EDITORIAL">EDITORIAL — Balanced and polished</option><option value="QUICK_CUT">QUICK CUT — Fast, energetic rhythm</option><option value="CINEMATIC">CINEMATIC — Slow, deliberate reveal</option><option value="TERMINAL">TERMINAL — Precise digital cadence</option><option value="QUIET">QUIET — Spacious, subtle pacing</option></select><small id="typewriterPresetHint">Balanced speed with a lime line cursor.</small>';phrases.closest('label')?.insertAdjacentElement('afterend',label);field=$('#settingTypewriterPreset');field?.addEventListener('change',()=>updateHeroTypewriterPresetPreview());return field}
function updateHeroTypewriterPresetPreview(){const field=ensureHeroTypewriterPreset(),preset=field?.value||'EDITORIAL',meta=HERO_TYPEWRITER_PRESETS[preset]||HERO_TYPEWRITER_PRESETS.EDITORIAL,hint=$('#typewriterPresetHint'),preview=$('#heroCopyPreviewPhrase');if(hint)hint.textContent=meta.help;if(preview)preview.dataset.typewriterPreset=preset;updateHeroCopyPreview()}
function hydrateHeroTypewriterPreset(config={}){const field=ensureHeroTypewriterPreset();if(!field)return;field.value=heroTypewriterPresetFor(config);updateHeroTypewriterPresetPreview()}
function buildHeroTypewriterConfig(){const field=ensureHeroTypewriterPreset(),preset=field?.value||'EDITORIAL',base=HERO_TYPEWRITER_PRESETS[preset]||HERO_TYPEWRITER_PRESETS.EDITORIAL,phrases=($('#settingHeroTypewriterPhrases')?.value||'').split(/\n+/).map(value=>value.trim()).filter(Boolean).slice(0,12);return {enabled:true,phrases:phrases.length?phrases:['BRANDS THAT SELL.'],typeSpeed:base.typeSpeed,typeRandom:base.typeRandom,pause:base.pause,eraseSpeed:base.eraseSpeed,nextDelay:base.nextDelay,startDelay:base.startDelay,loop:base.loop}}
const loadMaintenanceBeforeTypewriterPreset=loadMaintenance;
loadMaintenance=async function(){await loadMaintenanceBeforeTypewriterPreset();try{const current=await api('/admin/maintenance/settings');hydrateHeroTypewriterPreset(current.settings?.typewriterConfig||{})}catch{hydrateHeroTypewriterPreset({})}};
$('#settingsForm')?.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();try{const value=id=>$(id)?.value||'',typewriterConfig=buildHeroTypewriterConfig(),data={siteName:value('#settingSiteName'),title:value('#settingTitle'),email:value('#settingEmail')||null,inquiryRecipientEmail:value('#settingInquiryRecipientEmail')||null,inquirySubject:value('#settingInquirySubject')||null,phone:value('#settingPhone')||null,location:value('#settingLocation')||null,availability:$('#settingAvailability')?.checked||false,availabilityLabel:value('#settingAvailabilityLabel')||null,linkedin:value('#settingLinkedin')||null,behance:value('#settingBehance')||null,dribbble:value('#settingDribbble')||null,instagram:value('#settingInstagram')||null,github:value('#settingGithub')||null,metaTitle:value('#settingMetaTitle')||null,metaDescription:value('#settingMetaDescription')||null,ogImage:value('#settingOgImage')||null,heroImage:value('#settingHeroImage')||null,heroLeadText:value('#settingHeroLeadText').trim()||'I DESIGN',heroTypewriterPhrases:typewriterConfig.phrases,typewriterConfig};await api('/admin/maintenance/settings',{method:'PATCH',body:JSON.stringify(data)});msg($('#settingsMsg'),'Settings saved — homepage typewriter updated.',true);loadMaintenance()}catch(error){msg($('#settingsMsg'),error.message)}} ,true);
